<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{createPage,deletePage,listPageGroups,listPages,updatePage,type CmsPage,type CmsPageGroup,type PageDraft}from'../../api/pages';const groups=ref<CmsPageGroup[]>([]),pages=ref<CmsPage[]>([]),visible=ref(false),editing=ref<number|null>(null),saving=ref(false);const form=reactive<PageDraft>({groupId:null,alias:'',name:'',bodyHtml:'',renderMode:'RICH_TEXT',embedUrl:null,sortOrder:0,enabled:true});const groupName=(id:number|null)=>id==null?'普通固定页':groups.value.find(g=>g.id===id)?.name||`#${id}`;const asPage=(row:unknown)=>row as CmsPage;onMounted(refresh);async function refresh(){[groups.value,pages.value]=await Promise.all([listPageGroups(),listPages()])}function open(row?:CmsPage){editing.value=row?.id??null;Object.assign(form,row?{groupId:row.groupId,alias:row.alias,name:row.name,bodyHtml:row.bodyHtml,renderMode:row.renderMode,embedUrl:row.embedUrl,sortOrder:row.sortOrder,enabled:row.enabled}:{groupId:null,alias:'',name:'',bodyHtml:'',renderMode:'RICH_TEXT',embedUrl:null,sortOrder:0,enabled:true});visible.value=true}async function save(){saving.value=true;try{editing.value==null?await createPage({...form}):await updatePage(editing.value,{...form});visible.value=false;ElMessage.success('固定页面已保存');await refresh()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}async function remove(row:CmsPage){try{await ElMessageBox.confirm(`确定删除固定页面“${row.name}”吗？`,'删除固定页面',{type:'warning'});await deletePage(row.id);await refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'删除失败')}}</script><template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">网站内容</p><h1>固定页面管理</h1><p class="subtitle">维护普通固定页面和页面组成员，公开 URL 由 alias 生成。</p></div><el-button data-testid="add-page" type="primary" @click="open()">新增页面</el-button></header><el-card shadow="never"><el-table :data="pages"><el-table-column prop="name" label="页面名称"/><el-table-column label="页面组"><template #default="s">{{groupName(s.row.groupId)}}</template></el-table-column><el-table-column prop="alias" label="Alias"/><el-table-column prop="renderMode" label="呈现方式"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="open(asPage(s.row))">编辑</el-button><el-button link type="danger" @click="remove(asPage(s.row))">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" :title="editing==null?'新增固定页面':'编辑固定页面'" width="720px"><el-form label-width="100px"><el-form-item label="页面名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="页面组"><el-select v-model="form.groupId" clearable style="width:100%"><el-option v-for="g in groups" :key="g.id" :label="g.name" :value="g.id"/></el-select></el-form-item><el-form-item label="Alias"><el-input v-model="form.alias"/></el-form-item><el-form-item label="呈现方式"><el-select v-model="form.renderMode" style="width:100%"><el-option label="富文本" value="RICH_TEXT"/><el-option label="外部嵌入占位" value="EMBED_PLACEHOLDER"/><el-option label="站内特殊页面" value="INTERNAL_STATIC"/></el-select></el-form-item><el-form-item label="正文"><el-input v-model="form.bodyHtml" type="textarea" :rows="10"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></main></template>
